#[inline]
pub fn asin(x: f64) -> f64 {
    if !x.is_finite() {
        return f64::NAN;
    }
    let ax = x.abs();
    if ax > 1.0_f64 {
        return f64::NAN;
    }
    if x == 0.0_f64 {
        return x;
    }
    if ax == 1.0_f64 {
        return if x.is_sign_negative() {
            -core::f64::consts::FRAC_PI_2
        } else {
            core::f64::consts::FRAC_PI_2
        };
    }
    crate::trig::atan::atan(x / ((1.0_f64 - x) * (1.0_f64 + x)).sqrt())
}

#[inline]
pub fn asinl(x: f128) -> f128 {
    if !x.is_finite() {
        return f128::NAN;
    }
    let ax = x.abs();
    if ax > 1.0_f128 {
        return f128::NAN;
    }
    if x == 0.0_f128 {
        return x;
    }
    if ax == 1.0_f128 {
        return if x.is_sign_negative() {
            -core::f128::consts::FRAC_PI_2
        } else {
            core::f128::consts::FRAC_PI_2
        };
    }
    let y = if ax <= 0.75_f128 {
        crate::trig::atan::atanl(ax / (-ax).mul_add(ax, 1.0_f128).sqrt())
    } else {
        let t = ((1.0_f128 - ax) * 0.5_f128).sqrt();
        let inner = crate::trig::atan::atanl(t / (-t).mul_add(t, 1.0_f128).sqrt());
        core::f128::consts::FRAC_PI_2 - 2.0_f128 * inner
    };
    if x.is_sign_negative() {
        -y
    } else {
        y
    }
}

#[inline]
pub fn asinf(x: f32) -> f32 {
    if !x.is_finite() {
        return f32::NAN;
    }
    let ax = x.abs();
    if ax > 1.0_f32 {
        return f32::NAN;
    }
    if x == 0.0_f32 {
        return x;
    }
    let y = if ax <= ASIN_INTERVAL_MAX_F32 {
        k_simple_f32(ax)
    } else {
        let t = ((1.0_f32 - ax) * 0.5_f32).sqrt();
        core::f32::consts::FRAC_PI_2 - 2.0_f32 * asinf(t)
    };
    if x.is_sign_negative() {
        -y
    } else {
        y
    }
}

#[inline]
pub fn asins(x: f16) -> f16 {
    let x32 = x as f32;
    if !x32.is_finite() || x32.abs() > 1.0_f32 {
        return f16::NAN;
    }
    if x32 == 0.0_f32 {
        return x;
    }
    let ax = x.abs();
    let y = if ax <= (ASIN_INTERVAL_MAX_F32 as f16) {
        k_simple_f16(ax)
    } else {
        let t = (((1.0_f32 - x32.abs()) * 0.5_f32).sqrt()) as f16;
        (core::f32::consts::FRAC_PI_2 as f16) - 2.0_f16 * asins(t)
    };
    if x32.is_sign_negative() {
        -y
    } else {
        y
    }
}

#[cfg(feature = "mx")]
#[inline]
pub fn asin_fp4_e2m1(x: Fp4E2M1) -> Fp4E2M1 {
    let x32 = f32::from(x);
    if !x32.is_finite() {
        return Fp4E2M1::from(f32::NAN);
    }
    let ax32 = x32.abs();
    if ax32 > 1.0_f32 {
        return Fp4E2M1::from(f32::NAN);
    }
    if x32 == 0.0_f32 {
        return x;
    }
    let y = if ax32 <= ASIN_INTERVAL_MAX_F32 {
        k_simple_fp4_e2m1(Fp4E2M1::from(ax32))
    } else {
        let t = Fp4E2M1::from(((1.0_f32 - ax32) * 0.5_f32).sqrt());
        Fp4E2M1::from(core::f32::consts::FRAC_PI_2) - Fp4E2M1::from(2.0_f32) * asin_fp4_e2m1(t)
    };
    if x32.is_sign_negative() {
        -y
    } else {
        y
    }
}

